    def _time_left():
        return budget_s - (time.time() - start_time)

    # Phase 1: Progressive resolution increase
    # For each resolution, do multi-temperature SLSQP optimization
    resolutions = [640, 1280, 2560]

    for n_pts in resolutions:
        if _time_left() < 80:
