        # Random restart at this resolution
        if _time_left() > 50:
            h_rand = 0.7 * upsample_h(best_h, n_pts) + 0.3 * rng.rand(n_pts)
            h_rand = make_feasible(h_rand, n_pts)
            try:
                h_opt = _slsqp_optimize(h_rand, n_pts, 50.0, 250)
                c5_opt = compute_c5(h_opt)
                if c5_opt < best_c5:
                    best_c5 = c5_opt
                    best_h = h_opt.copy()
            except Exception:
                pass

        # Another restart with binary-like init
        if _time_left() > 40:
            h_bin = (rng.rand(n_pts) < 0.5).astype(float)
            h_bin = make_feasible(h_bin, n_pts)
            # Blend with best
            h_blend = 0.5 * upsample_h(best_h, n_pts) + 0.5 * h_bin
            h_blend = make_feasible(h_blend, n_pts)
