    # Phase 2: Coordinate descent polish at manageable resolution
    n_pts = len(best_h)
    # If too large, work at reduced resolution for CD then project back
    cd_n = min(n_pts, 1280)
    if cd_n < n_pts:
        h_cd = upsample_h(best_h, cd_n)
    else:
        h_cd = best_h.copy()

    cd_increments = [0.01, -0.01, 0.02, -0.02, 0.005, -0.005, 0.05, -0.05]

    for cd_round in range(10):
