        improved = False
        for j in range(cd_n):
            if _time_left() < 15:
                break
            old_val = h_cd[j]
            for delta in cd_increments:
                candidate = old_val + delta
                if candidate < 0.0 or candidate > 1.0:
                    continue
                trial = h_cd.copy()
                trial[j] = candidate
                trial = make_feasible(trial, cd_n)
                c = compute_c5(trial)
                if c < best_c5 - 1e-12:
                    best_c5 = c
                    h_cd = trial
                    old_val = candidate
                    improved = True
            for bv in (0.0, 1.0):
