                trial = h_cd.copy()
                trial[j] = bv
                trial = make_feasible(trial, cd_n)
                c = compute_c5(trial)
                if c < best_c5 - 1e-12:
                    best_c5 = c
                    h_cd = trial
                    improved = True
        if not improved:
            break

    # If we polished at reduced resolution, try to improve at full resolution
    if cd_n < n_pts:
        if compute_c5(h_cd) < best_c5:
            best_c5 = compute_c5(h_cd)
            best_h = upsample_h(h_cd, n_pts)
        else:
            # Use the CD result as new starting point for SLSQP at full res
            h_full = upsample_h(h_cd, n_pts)
            if _time_left() > 30:
                try:
                    h_opt = _slsqp_optimize(h_full, n_pts, 200.0, 150)
                    c5_opt = compute_c5(h_opt)
                    if c5_opt < best_c5:
                        best_c5 = c5_opt
                        best_h = h_opt.copy()
                except Exception:
                    pass
    else:
        if compute_c5(h_cd) < best_c5:
            best_c5 = compute_c5(h_cd)
            best_h = h_cd.copy()

    # Final: one more SLSQP pass at highest T from best
    if _time_left() > 20:
        n_final = len(best_h)
        try:
            h_opt = _slsqp_optimize(best_h, n_final, 2000.0, 100)
            c5_opt = compute_c5(h_opt)
            if c5_opt < best_c5:
                best_c5 = c5_opt
                best_h = h_opt.copy()
        except Exception:
            pass

    best_h = make_feasible(best_h, len(best_h))
    final_c5 = compute_c5(best_h)
    if final_c5 < best_c5:
        best_c5 = final_c5

    return best_h, best_c5, len(best_h)
